import sqlite3
import subprocess
from langchain_core.tools import tool
ZONE_DB = '/var/lib/dnsmgr/zones.db'


def _reload_zone(zone: str) -> None:
    # Ask the local name server to reload the zone so the new TTL takes effect
    subprocess.run(['rndc', 'reload', zone], capture_output=True, text=True, timeout=30, check=False)


@tool
def set_record_ttl(zone: str, name: str, record_type: str, ttl: int) -> str:
    if not zone or not zone.strip():
        return 'error: zone is required'
    if not name or not name.strip():
        return 'error: name is required'
    rtype = record_type.upper().strip()
    if rtype not in {'A', 'AAAA', 'CNAME', 'MX', 'TXT', 'NS', 'SRV'}:
        return 'error: unsupported record type'
    if not isinstance(ttl, int) or ttl < 60 or ttl > 86400:
        return 'error: ttl must be between 60 and 86400'
    conn = sqlite3.connect(ZONE_DB)
    try:
        cur = conn.execute('UPDATE records SET ttl = ? WHERE zone = ? AND name = ? AND type = ?', (ttl, zone.strip().lower(), name.strip().lower(), rtype))
        conn.commit()
    finally:
        conn.close()
    if cur.rowcount == 0:
        return 'error: record not found'
    _reload_zone(zone.strip().lower())
    return f'updated {cur.rowcount} record(s) to ttl {ttl}'
